String? growthClassificationLabel(String? indicator, String? code) =>
    growthClassificationLabels['${indicator?.toUpperCase()}:${code?.toUpperCase()}'];

String? growthClassificationCodeForLabel(String? label) {
  if (label == null) return null;
  final normalized = label.trim().toLowerCase();
  for (final entry in growthClassificationLabels.entries) {
    if (entry.value.toLowerCase() == normalized) return entry.key.split(':').last;
  }
  return null;
}
